package com.ias.finance;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import com.ias.trust.Problem;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class TrustedFinanceAccessTest {
 MockHttpServletRequest request;Map<String,Object> identity;Map<String,Object> member;TrustedFinanceAccess access;
 @BeforeEach void setup(){request=new MockHttpServletRequest();request.addHeader("Cookie","IAS-SESSION-DEV=synthetic_finance_session");request.addHeader("Origin","http://127.0.0.1:5173");request.addHeader("X-CSRF-TOKEN","synthetic_csrf_only");identity=new HashMap<>(Map.of("tenantId","1","userId","99","identityType","CUSTOMER","enabled",true,"permissions",List.of("finance.quote.read","finance.quote.confirm")));member=new HashMap<>(Map.of("tenantId","1","companyId","2","userId","99","active",true,"administrator",true));access=new TrustedFinanceAccess((edge,path,b,r)->{var result=new HashMap<>(edge.equals("finance-identity")?identity:member);result.put("checkedAt",Instant.now().toString());return result;});}
 @Test void currentMembershipAndAdminAreRecheckedOnEveryCall(){var p=access.principal(request,true);var bound=access.bind(request,p);var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());bound.current(p.actor(),owner,"CUSTOMER_QUOTE_CONFIRMED");member.put("administrator",false);assertEquals(403,assertThrows(Problem.class,()->bound.current(p.actor(),owner,"CUSTOMER_QUOTE_CONFIRMED")).status);member.put("administrator",true);member.put("companyId","3");assertThrows(Problem.class,()->bound.current(p.actor(),owner,"READ"));}
 @Test void identityChangeAndRevokedCapabilityAreNeverCached(){var p=access.principal(request,true);var bound=access.bind(request,p);var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());identity.put("userId","100");assertEquals(401,assertThrows(Problem.class,()->bound.current(p.actor(),owner,"CUSTOMER_QUOTE_CONFIRMED")).status);identity.put("userId","99");identity.put("permissions",List.of("finance.quote.read"));assertEquals(403,assertThrows(Problem.class,()->bound.current(p.actor(),owner,"CUSTOMER_QUOTE_CONFIRMED")).status);}
 @Test void writeRequiresOriginAndOneCsrfHeaderBeforeCallingOwner(){var p=access.principal(request,false);request.removeHeader("X-CSRF-TOKEN");assertEquals(403,assertThrows(Problem.class,()->access.bind(request,p).current(p.actor(),new FeeGroup.Identity(1,2,UUID.randomUUID()),"CUSTOMER_QUOTE_CONFIRMED")).status);}
 @Test void staleOwnerFactFailsClosed(){var stale=new TrustedFinanceAccess((edge,path,b,r)->{var result=new HashMap<>(identity);result.put("checkedAt",Instant.now().minusSeconds(5).toString());return result;});assertEquals(503,assertThrows(Problem.class,()->stale.principal(request,false)).status);}
 @Test void freezeProofMustBindExactGroupVersionOperationQuoteAndCompleteDigest(){
  UUID ticket=UUID.randomUUID(),round=UUID.randomUUID(),relation=UUID.randomUUID();var wrong=new java.util.concurrent.atomic.AtomicBoolean(false);var ready=new java.util.concurrent.atomic.AtomicBoolean(true);
  var adapter=new TrustedFinanceAccess((edge,path,b,r)->{var f=new HashMap<String,Object>();if(edge.equals("finance-ticket")){f.putAll(Map.of("tenantId","1","companyId","2","ticketId",ticket.toString(),"roundId",round.toString(),"faultRelationId",relation.toString()));if(path.endsWith("/prepare")){for(String field:List.of("groupId","expectedGroupVersion","quoteId","operationId","commandDigest"))f.put(field,b.get(field));if(wrong.get())f.put("commandDigest","0".repeat(64));f.put("quoteWritable",true);f.put("coordinationState","FROZEN");f.put("globalFreezeAck",true);f.put("freezeId",UUID.randomUUID().toString());f.put("generation","1");f.put("requiredOwners",List.of("approval","stock"));f.put("executionBarrierClear",ready.get());}}else if(edge.equals("finance-approval")){f.putAll(Map.of("published",true,"version","PUBLISHED_V1","thresholdCents","200000"));}f.put("checkedAt",Instant.now().toString());return f;});
  var p=new FinanceAccess.Principal(new JdbcFeeGroups.Actor(1,10),"EMPLOYEE");var scope=adapter.scope(request,p,ticket);UUID line=UUID.randomUUID();var command=new FeeGroup.Submit(UUID.randomUUID(),UUID.randomUUID(),0,Set.of(),List.of(new FeeGroup.PlanLine(line,ticket,round,100,false)),new FeeGroup.PublishedRule("PUBLISHED_V1",200000));var details=new JdbcFeeGroups.QuoteDetails(true,"完整报价摘要",Map.of(line,"LABOR"));var bound=adapter.bind(request,p);bound.sourceRegistration(p.actor(),scope.owner(),command,details);var wrongRule=new FeeGroup.Submit(command.operationId(),command.applicationId(),0,Set.of(),command.additions(),new FeeGroup.PublishedRule("PUBLISHED_NOT_CURRENT",300000));assertEquals("FEE_RULE_CHANGED",assertThrows(Problem.class,()->bound.sourceRegistration(p.actor(),scope.owner(),wrongRule,details)).code);bound.submission(p.actor(),scope.owner(),command,details);wrong.set(true);assertEquals("FINANCE_FREEZE_PROOF_MISMATCH",assertThrows(Problem.class,()->bound.submission(p.actor(),scope.owner(),command,details)).code);wrong.set(false);ready.set(false);assertEquals("FINANCE_EXECUTION_FREEZE_NOT_CONFIRMED",assertThrows(Problem.class,()->bound.submission(p.actor(),scope.owner(),command,details)).code);
 }
 @Test void canonicalDigestBindsPricingAndChargingNotMapOrSetIteration(){UUID a=UUID.randomUUID(),b=UUID.randomUUID(),line1=UUID.randomUUID(),line2=UUID.randomUUID(),ticket=UUID.randomUUID(),round=UUID.randomUUID(),operation=UUID.randomUUID(),quote=UUID.randomUUID();var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());var lines=List.of(new FeeGroup.PlanLine(line1,ticket,round,100,false),new FeeGroup.PlanLine(line2,ticket,round,200,false));var first=new FeeGroup.Submit(operation,quote,1,new LinkedHashSet<>(List.of(a,b)),lines,new FeeGroup.PublishedRule("PUBLISHED",200000));var second=new FeeGroup.Submit(operation,quote,1,new LinkedHashSet<>(List.of(b,a)),lines,first.rule());var kinds1=new LinkedHashMap<UUID,String>();kinds1.put(line1,"LABOR");kinds1.put(line2,"OTHER");var kinds2=new LinkedHashMap<UUID,String>();kinds2.put(line2,"OTHER");kinds2.put(line1,"LABOR");var details=new JdbcFeeGroups.QuoteDetails(true,"报价摘要",kinds1);assertEquals(JdbcFeeGroups.quoteDigest(owner,first,details),JdbcFeeGroups.quoteDigest(owner,second,new JdbcFeeGroups.QuoteDetails(true,"报价摘要",kinds2)));assertNotEquals(JdbcFeeGroups.quoteDigest(owner,first,details),JdbcFeeGroups.quoteDigest(owner,first,new JdbcFeeGroups.QuoteDetails(false,"报价摘要",kinds2)));}
 @Test void quoteWriteNeverGrantsMoneyAndCurrentMoneyCapabilityIsRechecked(){identity.put("identityType","EMPLOYEE");identity.put("userId","10");identity.put("departmentEnabled",true);identity.put("companyIds",List.of("2"));identity.put("permissions",List.of("finance.quote.read","finance.quote.write"));var p=access.principal(request,true);var o=new FeeGroup.Identity(1,2,UUID.randomUUID());var ledger=access.ledger(request,p);assertEquals(403,assertThrows(Problem.class,()->ledger.current(p.actor(),o,"COLLECTION_RECORDED")).status);identity.put("permissions",List.of("finance.money.collect"));ledger.current(p.actor(),o,"COLLECTION_RECORDED");identity.put("permissions",List.of());assertEquals(403,assertThrows(Problem.class,()->ledger.current(p.actor(),o,"COLLECTION_RECORDED")).status);}
 @Test void feeReadProjectionUsesItsOwnCapabilityWithoutQuoteOrMoney(){identity.put("identityType","EMPLOYEE");identity.put("userId","10");identity.put("departmentEnabled",true);identity.put("departmentId","5");identity.put("companyIds",List.of("2"));identity.put("permissions",List.of("approval.fees.read"));var p=access.feePrincipal(request);var bound=access.feeBind(request,p);var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());bound.current(p.actor(),owner,"READ");assertEquals(403,assertThrows(Problem.class,()->bound.current(p.actor(),owner,"CUSTOMER_QUOTE_CONFIRMED")).status);identity.put("permissions",List.of("finance.money.read","finance.quote.read"));assertEquals(403,assertThrows(Problem.class,()->access.feePrincipal(request)).status);identity.put("companyIds",List.of("3"));identity.put("permissions",List.of("approval.fees.read"));assertEquals(404,assertThrows(Problem.class,()->access.feeBind(request,p).current(p.actor(),owner,"READ")).status);}
 @Test void reverseAndRebookWithoutVerifiedCorrectionFailClosed(){identity.put("identityType","EMPLOYEE");identity.put("userId","10");identity.put("enabled",true);identity.put("permissions",List.of("finance.money.read","finance.money.reverse","finance.money.collect"));var p=new FinanceAccess.Principal(new JdbcFeeGroups.Actor(1,10),"EMPLOYEE");var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());var ledger=access.ledger(request,p);UUID payment=UUID.randomUUID(),evidence=UUID.randomUUID();var reverse=new JdbcMoneyLedger.Reverse(0,0,payment,evidence,"test-only");var reverseFailure=assertThrows(Problem.class,()->ledger.verify(p.actor(),owner,UUID.randomUUID(),reverse));assertEquals(503,reverseFailure.status);assertEquals("FINANCE_CORRECTION_EVIDENCE_PENDING",reverseFailure.code);var rebook=new JdbcMoneyLedger.Rebook(0,0,payment,evidence,"test-only",new JdbcMoneyLedger.Collect(0,0,UUID.randomUUID(),new MoneyLedger.Payment(UUID.randomUUID(),UUID.randomUUID(),1,new MoneyLedger.Voucher("ref",java.time.LocalDate.parse("2026-10-28"),"BANK",UUID.randomUUID(),"a".repeat(64)),null)).payment());var rebookFailure=assertThrows(Problem.class,()->ledger.verify(p.actor(),owner,UUID.randomUUID(),rebook));assertEquals(503,rebookFailure.status);assertEquals("FINANCE_CORRECTION_EVIDENCE_PENDING",rebookFailure.code);}
 @Test void explicitMoneyCapabilityStillCannotFakeCompletedOwnerFacts(){identity.put("identityType","EMPLOYEE");identity.put("userId","10");identity.put("departmentEnabled",true);identity.put("companyIds",List.of("2"));identity.put("permissions",List.of("finance.money.assess"));var p=access.principal(request,true);var o=new FeeGroup.Identity(1,2,UUID.randomUUID());var ledger=access.ledger(request,p);ledger.current(p.actor(),o,"RECEIVABLE_ASSESSED");var command=new JdbcMoneyLedger.Assess(0,0,UUID.randomUUID(),new MoneyLedger.Approval(UUID.randomUUID(),"a".repeat(64),Map.of(UUID.randomUUID(),1000L)));assertEquals("FINANCE_COMPLETED_APPROVAL_FACT_PENDING",assertThrows(Problem.class,()->ledger.verify(p.actor(),o,UUID.randomUUID(),command)).code);}}
